<script setup lang="ts">
import {ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,ensureSession,errorText,session} from '../lib/api';import Icon from '../components/Icon.vue';import SiteLogo from '../components/SiteLogo.vue';import Notice from '../components/Notice.vue'
const route=useRoute(),router=useRouter(),username=ref(''),password=ref(''),busy=ref(false),error=ref(String(route.query.error||''))
async function submit(){busy.value=true;error.value='';try{await api('/api/auth/login',{method:'POST',body:{username:username.value,password:password.value}});password.value='';session.checked=false;if(!await ensureSession(true))throw new Error('会话建立失败，请检查 Cookie 设置。');const next=String(route.query.next||'/admin/stats');await router.replace(next.startsWith('/admin/')&&!next.startsWith('/admin/login')?next:'/admin/stats')}catch(e){error.value=errorText(e);password.value=''}finally{busy.value=false}}
</script>
<template><main id="main-content" class="login-page"><RouterLink to="/" class="brand"><span class="brand-mark"><SiteLogo :size="24"/></span><span>cfspeed<small>DNS SYNC SERVICE</small></span></RouterLink><section class="login-card card"><span class="eyebrow">ADMIN LOGIN</span><h1>管理员登录</h1><p class="muted">登录管理后台。</p><Notice v-if="route.query.changed" message="密码已更新，请重新登录。" kind="success"/><Notice v-if="route.query.expired" message="会话已过期，请重新登录。" kind="info"/><form @submit.prevent="submit"><label class="field">用户名<input v-model="username" required autofocus autocomplete="username" maxlength="100" placeholder="管理员用户名"></label><label class="field">密码<input v-model="password" type="password" required autocomplete="current-password" maxlength="256" placeholder="请输入密码"></label><Notice :message="error"/><button class="btn primary wide" :disabled="busy">{{busy?'正在验证…':'登录'}}<Icon name="arrow" :size="18"/></button></form><p class="help login-help"><Icon name="lock" :size="15"/> 请勿在公用设备上保存密码。</p></section><p class="login-foot">初始管理员凭据保存在服务器数据目录。</p><a href="/ipTop.html" class="text-link">查看 IP 接口 <Icon name="external" :size="15"/></a></main></template>
